scwin.trigger1_onclick = function(e) {
    // depth가 1까지만 열기 (하위 다 닫힘)
    gridView1.spanAll(1);
};
scwin.trigger2_onclick = function(e) {
    // 모두 열림
    gridView1.spanAll(true);
};
scwin.gridView1_oncellclick = function(row, col) {
    alert("cellClickEvent");
};
scwin.trigger3_onclick = function(e) {
    //gridView1.getAncestorRowIndexArray(9);
    //alert("Ascindex : " + gridView1.getAncestorRowIndexArray(9));
    msgAlert = gridView1.getAncestorRowIndexArray(9);
};
scwin.trigger4_onclick = function(e) {
    //gridView1.getDescendantRowIndexArray(2);
    //alert("Descindex : " + gridView1.getDescendantRowIndexArray(2));
    msgAlert = gridView1.getDescendantRowIndexArray(2);
};
scwin.compareTwoArrays = function(arr1, arr2) {
    return WebSquare.wUnit.getJq(arr1).not(arr2).length == 0 && WebSquare.wUnit.getJq(arr2).not(arr1).length == 0;
}
scwin.checkVal1 = function() {
    return scwin.compareTwoArrays(msgAlert, [7]) == true;
}
scwin.checkVal2 = function() {
    return scwin.compareTwoArrays(msgAlert, [3, 4, 5, 6]) == true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플 실행 후 'gridView1.getAncestorRowIndexArray(9);'버튼을 클릭한다.
    //1. After running the sample, click the 'gridView1.getAncestorRowIndexArray (9);' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 상위노드의 인덱스인 7을 가져온다.
    //1. Get the index 7 of the ancestor node.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 'gridView1.getDescendantRowIndexArray(2);'버튼을 클릭한다.
    //2. Click the 'gridView1.getDescendantRowIndexArray (2);' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 2. 하위노드의 인덱스인 3,4,5,6이 보여진다.
    //2. The indexes of the child nodes 3, 4, 5, and 6 are shown. 
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //테스트 데이터 셋팅
    scwin.init();
    // 모두 닫기
    //모두 펼치기
    window.msgAlert = undefined;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
